+<!DOCTYPE html>
+<html lang="zh-CN">
+<head>
+<meta charset="utf-8" />
+<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />
+<title>万用搭子 · v0</title>
+<style>
+  :root { color-scheme: dark; }
+  * { box-sizing: border-box; }
+  html, body { height: 100%; }
+  body { margin:0; font:14px/1.45 -apple-system,"PingFang SC",system-ui,sans-serif;
+         background:#0e1116; color:#e6edf3; padding:10px; display:flex; gap:10px; overflow:hidden; }
+  #left { flex:0 0 42%; display:flex; flex-direction:column; gap:8px; min-width:0; }
+  #right { flex:1 1 auto; display:flex; flex-direction:column; gap:8px; min-width:0; }
+  .card { background:#161b22; border:1px solid #21262d; border-radius:10px; padding:10px; }
+  #ctrl { flex:0 0 33%; overflow:auto; padding:8px 10px; }
+  #prevCard { flex:1 1 auto; display:flex; flex-direction:column; min-height:0; }
+  h1 { font-size:16px; margin:0 0 6px; letter-spacing:.5px; }
+  #upstream { display:flex; align-items:center; gap:8px; border-left:4px solid #4285f4;
+              background:#4285f41a; border-radius:8px; padding:6px 8px; margin-bottom:6px;
+              overflow:hidden; min-width:0; }
+  #upstream img { width:26px; height:26px; flex:0 0 auto; }
+  .up-name { font-size:15px; font-weight:700; line-height:1.2; }
+  .up-sub { font-size:10px; color:#8b949e; font-family:ui-monospace,monospace; overflow-wrap:anywhere; }
+  .up-google { border-left-color:#4285f4; background:#4285f41a; }
+  .up-google .up-name { color:#79c0ff; }
+  .up-qwen { border-left-color:#ff8a3d; background:#ff8a3d1a; }
+  .up-qwen .up-name { color:#ffb37a; }
+  .up-unk { border-left-color:#8b949e; background:transparent; }
+  .up-unk .up-name { color:#8b949e; }
+  .row { display:flex; gap:6px; align-items:center; margin-top:6px; }
+  .row > * { flex:1; min-width:0; }
+  .row2 { display:flex; gap:6px; align-items:center; margin-top:5px; }
+  .row2 > * { min-width:0; }
+  .row2 > .lb { flex:0 0 56px; font-size:12px; color:#8b949e; }
+  select, input[type=text] { width:100%; padding:5px 7px; border-radius:7px; border:1px solid #30363d;
+         background:#0d1117; color:#e6edf3; font:inherit; font-size:13px; }
+  select:disabled { opacity:.35; }
+  .radios { display:flex; gap:12px; flex:1 1 auto; }
+  .radios label { display:flex; align-items:center; gap:4px; font-size:13px; cursor:pointer; }
+  .radios input { accent-color:#238636; }
+  button { padding:8px 12px; border-radius:8px; border:0; background:#238636; color:#fff; font-weight:600; }
+  button.alt { background:#21262d; color:#e6edf3; border:1px solid #30363d; }
+  button:disabled { opacity:.5; }
+  video { width:100%; flex:1 1 auto; min-height:0; border-radius:8px; background:#000; object-fit:contain; }
+  .badge { display:inline-block; font-size:11px; padding:1px 7px; border-radius:999px;
+           background:#1f6feb33; color:#79c0ff; margin-left:6px; }
+  .warn { background:#9e6a0322; border-color:#9e6a03; color:#ffd33d; font-size:12px; }
+  .ask { border-color:#d29922; background:#9e6a0322; color:#ffd33d; font-size:13px; line-height:1.5; }
+  .pulse { animation:p 1.2s infinite; }
+  @keyframes p { 50% { opacity:.45 } }
+  #logCard { flex:1 1 auto; display:flex; flex-direction:column; min-height:0; }
+  #log { flex:1 1 auto; overflow:auto; font:12px/1.5 ui-monospace,monospace; }
+  #log .ln { display:flex; gap:6px; padding:1px 0; }
+  #log .ts { color:#56606b; flex:0 0 auto; }
+  #log .bd { flex:0 0 auto; }
+  #log .ms { flex:1 1 auto; white-space:pre-wrap; word-break:break-word; }
+  .k-sys .ms { color:#6e7681; } .k-you .ms { color:#79c0ff; } .k-model .ms { color:#7ee787; }
+  .k-tool .ms { color:#ffb37a; } .k-pi .ms { color:#d2a8ff; } .k-ask .ms { color:#ffd33d; }
+  .k-prog .ms { color:#79c0ff; } .k-err .ms { color:#ff7b72; }
+  #logHead { font-size:12px; color:#8b949e; float:right; }
+  .radios label { white-space:nowrap; }
+  .up-sub { white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
+  /* 窄屏（手机）：改为上下堆叠，避免两栏互相挤压 */
+  @media (max-width: 900px) {
+    html, body { height:auto; }
+    body { flex-direction:column; overflow:auto; }
+    #left, #right { flex:1 1 auto; }
+    #ctrl { flex:0 0 auto; }
+    #prevCard { flex:0 0 auto; }
+    video { height:38vh; flex:0 0 auto; }
+    #log { max-height:42vh; }
+  }
+</style>
+</head>
+<body>
+  <div id="left">
+    <div class="card" id="ctrl">
+      <h1>万用搭子</h1>
+      <div id="upstream" class="up up-unk" style="display:none">
+        <img id="upIcon" src="data:image/png;base64," alt="Gemini">
+        <div>
+          <div class="up-name" id="upName">—</div>
+          <div class="up-sub" id="upSub"></div>
+        </div>
+      </div>
+      <div id="secWarn" class="card warn" style="display:none"></div>
+      <div class="row2"><span class="lb">搭子</span><span class="radios" id="personaGroup"></span></div>
+      <div class="row2"><span class="lb">推理档位</span>
+        <select id="thinking">
+          <option value="">关闭（普通款）</option>
+          <option value="low">低（ET · low）</option>
+          <option value="medium">中（ET · medium）</option>
+          <option value="high">高（ET · high）</option>
+        </select></div>
+      <div class="row2"><span class="lb">眼睛</span><span class="radios">
+        <label><input type="radio" name="source" value="camera" checked>摄像头</label>
+        <label><input type="radio" name="source" value="display">屏幕共享</label></span></div>
+      <div class="row2"><span class="lb">镜头</span>
+        <select id="camPicker"><option value="">自动</option></select></div>
+      <div class="row2"><span class="lb">帧率</span>
+        <select id="fps">
+          <option value="1">1 fps</option>
+          <option value="2">2 fps</option>
+          <option value="4" selected>4 fps</option>
+          <option value="6">6 fps</option>
+        </select></div>
+      <div class="row">
+        <button id="start">开始</button>
+        <button id="stop" class="alt" disabled>停止</button>
+      </div>
+    </div>
+
+    <div class="card" id="prevCard">
+      <label>预览 <span id="state" class="badge">未连接</span></label>
+      <video id="preview" playsinline muted></video>
+      <div class="row" style="margin-top:6px">
+        <input id="textInput" type="text" placeholder="文字输入（调试用）">
+        <button id="sendText" class="alt" style="flex:0 0 72px">发送</button>
+      </div>
+    </div>
+  </div>
+
+  <div id="right">
+    <div id="piAsk" class="card ask pulse" style="display:none"></div>
+    <div class="card" id="logCard">
+      <label>日志 <span id="logHead"><input type="checkbox" id="focusLog" checked style="vertical-align:-2px"> 只看重点</span></label>
+      <div id="log"></div>
+    </div>
+  </div>
+
+<script>
+const $ = (id) => document.getElementById(id);
+const pick = (name) => {
+  const el = document.querySelector(`input[name="${name}"]:checked`);
+  return el ? el.value : '';
+};
+const esc = (s) => String(s ?? '').replace(/[&<>"]/g,
+  (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
+
+// 日志：按来源上色 + 「只看重点」过滤（演示时一眼能看出：在跟模型说话 / 在调工具 / pi 在干活）
+const LOG_KINDS = {
+  you:      { badge: '🎙 你',   cls: 'k-you' },
+  model:    { badge: '🔊 搭子', cls: 'k-model' },
+  tool:     { badge: '🛠 工具', cls: 'k-tool' },
+  pi:       { badge: '🤖 pi',   cls: 'k-pi' },
+  ask:      { badge: '⏳ 决策', cls: 'k-ask' },
+  progress: { badge: '⏱ 进度', cls: 'k-prog' },
+  err:      { badge: '⚠️ 错误', cls: 'k-err' },
+  sys:      { badge: '',        cls: 'k-sys' },
+};
+const LOG_KEEP = 200;
+function log(m, kind = 'sys') {
+  const el = $('log'), k = LOG_KINDS[kind] || LOG_KINDS.sys;
+  const row = document.createElement('div');
+  row.className = 'ln ' + k.cls;
+  const ts = new Date().toLocaleTimeString('zh-CN', { hour12: false });
+  row.innerHTML = `<span class="ts">${ts}</span>` +
+    (k.badge ? `<span class="bd">${k.badge}</span>` : '') +
+    `<span class="ms">${esc(m)}</span>`;
+  el.appendChild(row);
+  while (el.children.length > LOG_KEEP) el.removeChild(el.firstChild);
+  if ($('focusLog').checked && kind === 'sys') row.style.display = 'none';
+  else el.scrollTop = 1e9;
+}
+$('focusLog').onchange = () => {
+  const on = $('focusLog').checked;
+  for (const row of $('log').children) {
+    row.style.display = (on && row.classList.contains('k-sys')) ? 'none' : '';
+  }
+};
+const b64 = (buf) => { let s = ''; const u = new Uint8Array(buf);
+  for (let i = 0; i < u.length; i += 0x8000) s += String.fromCharCode.apply(null, u.subarray(i, i + 0x8000));
+  return btoa(s); };
+const unb64 = (s) => { const bin = atob(s); const u = new Uint8Array(bin.length);
+  for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); return u; };
+
+let ws = null, audioCtx = null, micNode = null, worklet = null, playHead = 0, camTimer = null;
+let ready = false, wakeLock = null;
+
+const WORKLET = `
+class Cap extends AudioWorkletProcessor {
+  constructor(){ super(); this.buf = []; this.ratio = sampleRate / 16000; this.acc = 0; this.n = 0; }
+  process(inputs){
+    const ch = inputs[0][0]; if (!ch) return true;
+    for (let i = 0; i < ch.length; i++) {
+      this.acc += ch[i]; this.n++;
+      if (this.n >= this.ratio) { this.buf.push(Math.max(-1, Math.min(1, this.acc / this.n)));
+        this.acc = 0; this.n = 0; }
+    }
+    while (this.buf.length >= 512) {
+      const chunk = this.buf.splice(0, 512); const out = new Int16Array(512);
+      for (let i = 0; i < 512; i++) out[i] = chunk[i] * 32767;
+      this.port.postMessage(out.buffer, [out.buffer]);
+    }
+    return true;
+  }
+}
+registerProcessor('cap', Cap);`;
+
+// 摄像头列表：拿到权限后 label 才有意义，所以每次取流后都刷新一次
+async function refreshCams(activeId) {
+  try {
+    const devs = (await navigator.mediaDevices.enumerateDevices())
+      .filter((d) => d.kind === 'videoinput');
+    const sel = $('camPicker');
+    const saved = activeId || (() => { try { return localStorage.getItem('cam.deviceId') || ''; } catch (e) { return ''; } })();
+    sel.innerHTML = '<option value="">自动（让浏览器选）</option>' + devs.map((d, i) =>
+      `<option value="${d.deviceId}"${d.deviceId === saved ? ' selected' : ''}>` +
+      `${esc(d.label || ('摄像头 ' + (i + 1)))}</option>`).join('');
+    if (devs.length > 1) log(`发现 ${devs.length} 个摄像头，可在「镜头」里切换（视角差异通常很大）`);
+  } catch (e) { /* 无权限时忽略 */ }
+}
+
+async function loadPersonas() {
+  const r = await fetch('/api/personas'); const d = await r.json();
+  $('personaGroup').innerHTML = d.items.map(i =>
+    `<label title="${esc(i.tagline)}"><input type="radio" name="persona" value="${i.id}"` +
+    `${i.id === d.default ? ' checked' : ''}>${esc(i.name)}</label>`).join('');
+}
+
+function wsURL() { return (location.protocol === 'https:' ? 'wss://' : 'ws://') + location.host + '/ws/client'; }
+
+function connect() {
+  ws = new WebSocket(wsURL());
+  ws.onopen = () => { log('WS 已连接（本机中继）');
+    const th = $('thinking').value;
+    try { localStorage.setItem('live.thinking', th); } catch (e) {}
+    try { localStorage.setItem('live.fps', $('fps').value); } catch (e) {}
+    ws.send(JSON.stringify({ type: 'start', persona: pick('persona'), thinking: th })); };
+  ws.onclose = () => { log('WS 已断开'); setState('已断开'); };
+  ws.onerror = () => log('WS 错误');
+  ws.onmessage = (ev) => handle(JSON.parse(ev.data));
+}
+
+function setState(t) { $('state').textContent = t; }
+
+function handle(msg) {
+  if (msg.type === 'starting') {
+    setState('连接中…');
+    if (msg.model) { $('upName').textContent = (msg.label || msg.model);
+      $('upSub').textContent = `model=${msg.model}`; }
+    log(`启动上游：persona=${msg.persona} · model=${msg.model || '?'} · ${msg.label || ''}`);
+    return;
+  }
+  if (msg.type === 'ready') { ready = true; setState('就绪');
+    log(`上游就绪 · persona=${msg.persona}` + (msg.model ? ` · model=${msg.model}` : '')
+        + (msg.thinking ? ` · thinking=${msg.thinking}` : ' · 无思考档'));
+    return; }
+  if (msg.type === 'log') { log(msg.message, msg.kind === 'pi' ? 'pi' : (msg.kind || 'sys')); return; }
+  // pi 需要你拍板：等你的语音回答（中途不答会超时自动取消）
+  if (msg.type === 'pi_dialog') {
+    const opts = (msg.options || []).join(' / ');
+    $('piAsk').style.display = 'block';
+    $('piAsk').innerHTML =
+      `⏳ <b>pi 等你拍板</b>（${Math.round(msg.deadlineIn || 0)}s 内不答自动取消）<br>`
+      + (msg.title ? `<b>${esc(msg.title)}</b><br>` : '')
+      + (msg.message ? `${esc(msg.message)}<br>` : '')
+      + (opts ? `选项：${esc(opts)}<br>` : '')
+      + (msg.needsPassphrase ? '⚠ 放行类请求：请先完整听操作，再说出完整口令' : '');
+    log(`pi 决策请求 [${msg.method}] ${msg.title || ''}（request_id=${msg.id}）`);
+    return;
+  }
+  if (msg.type === 'pi_dialog_done') {
+    $('piAsk').style.display = 'none';
+    log(`pi 决策已处理：${msg.result || ''}`);
+    return;
+  }
+  if (msg.type === 'error') { log('错误: ' + msg.message, 'err'); setState('错误'); return; }
+  if (msg.type === 'closed') { setState('上游已关闭'); return; }
+  if (msg.type === 'tool_call') {
+    const a = msg.args || {};
+    const brief = a.path || a.prompt || a.source || a.request_id || '';
+    log(`调用 ${msg.name}${brief ? ' · ' + String(brief).slice(0, 60) : ''}`, 'tool');
+    return;
+  }
+  if (msg.type === 'tool_result') {
+    log(`${msg.ok ? '✓' : '✗'} ${msg.name} — ${msg.summary || ''}`, 'tool');
+    return;
+  }
+  if (msg.type === 'upstream') { const sc = msg.payload.serverContent || {};
+    if (sc.inputTranscription?.text) log(sc.inputTranscription.text, 'you');
+    if (sc.outputTranscription?.text) log(sc.outputTranscription.text, 'model');
+    for (const p of (sc.modelTurn?.parts || [])) {
+      const d = p.inlineData; if (!d?.data) continue;
+      if ((d.mimeType || '').startsWith('audio/')) playAudio(d.data, d.mimeType);
+    }
+  }
+}
+
+function playAudio(data, mime) {
+  const rate = parseInt((mime.match(/rate=(\d+)/) || [])[1] || '24000', 10);
+  const pcm = new Int16Array(unb64(data).buffer);
+  const f32 = new Float32Array(pcm.length);
+  for (let i = 0; i < pcm.length; i++) f32[i] = pcm[i] / 32768;
+  const ab = audioCtx.createBuffer(1, f32.length, rate);
+  ab.copyToChannel(f32, 0);
+  const src = audioCtx.createBufferSource();
+  src.buffer = ab; src.connect(audioCtx.destination);
+  playHead = Math.max(playHead, audioCtx.currentTime);
+  src.start(playHead); playHead += ab.duration;
+}
+
+async function start() {
+  refreshStatus();   // 换实现后重启服务端时，横幅能跟着更新
+  if (!window.isSecureContext && location.hostname !== 'localhost' && location.hostname !== '127.0.0.1') {
+    log('⚠ 非安全上下文：浏览器会拒绝摄像头/麦克风。请改用 HTTPS，或用 Chrome 的 --unsafely-treat-insecure-origin-as-secure');
+  }
+  audioCtx = new AudioContext();
+  const blob = new Blob([WORKLET], { type: 'application/javascript' });
+  const url = URL.createObjectURL(blob);
+  await audioCtx.audioWorklet.addModule(url);
+  playHead = 0;
+
+  const mode = pick('source') || 'camera';
+  let stream;
+  const camId = $('camPicker').value;
+  try {
+    if (mode === 'display') {
+      stream = await navigator.mediaDevices.getDisplayMedia({ video: { frameRate: 1 }, audio: false });
+    } else {
+      // 镜头/视角：facingMode 用 ideal（硬约束在某些设备上会直接失败）
+      const video = camId
+        ? { deviceId: { exact: camId }, width: { ideal: 1280 }, height: { ideal: 720 } }
+        : { facingMode: { ideal: 'environment' }, width: { ideal: 1280 }, height: { ideal: 720 } };
+      try {
+        stream = await navigator.mediaDevices.getUserMedia({ video, audio: false });
+      } catch (e) {
+        log('指定镜头取流失败，回退默认：' + e.message);
+        stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
+      }
+    }
+  } catch (e) { log('视觉采集失败: ' + e.message); return; }
+
+  // 摄像头：尽量把视角拉广 + 报出实际拿到什么
+  if (mode === 'camera') {
+    const track = stream.getVideoTracks()[0];
+    try {
+      const caps = track.getCapabilities ? track.getCapabilities() : {};
+      if (caps.zoom && typeof caps.zoom.min === 'number') {
+        await track.applyConstraints({ advanced: [{ zoom: caps.zoom.min }] });
+        log(`视角：zoom 可调 ${caps.zoom.min}–${caps.zoom.max}，已拉到最广 ${caps.zoom.min}`);
+      } else {
+        log('视角：本设备/浏览器不暴露 zoom，只能用当前镜头本身（想更广请选超广角镜头）');
+      }
+    } catch (e) { log('zoom 调整失败（不影响使用）: ' + e.message); }
+    const st = track.getSettings ? track.getSettings() : {};
+    log(`镜头: ${track.label || '未命名'} · ${st.width}×${st.height} · zoom=${st.zoom ?? '-'}`);
+    if (st.deviceId) { try { localStorage.setItem('cam.deviceId', st.deviceId); } catch (e) {} }
+    refreshCams(st.deviceId);
+  } else {
+    log(`屏幕共享已开启（镜头选择仅摄像头模式生效）`);
+  }
+
+  $('preview').srcObject = stream;
+  await $('preview').play().catch(() => {});
+
+  // 麦克风（16k PCM）
+  try {
+    const mic = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
+    const src = audioCtx.createMediaStreamSource(mic);
+    micNode = new AudioWorkletNode(audioCtx, 'cap');
+    micNode.port.onmessage = (e) => {
+      if (ws?.readyState === 1 && ready) ws.send(JSON.stringify({ type: 'audio', data: b64(e.data) }));
+    };
+    src.connect(micNode);
+    log('麦克风已开启（16kHz PCM 上行）');
+  } catch (e) { log('麦克风失败: ' + e.message); }
+
+  connect();
+  $('start').disabled = true; $('stop').disabled = false;
+  setState('连接中…');
+
+  // 视觉：可调帧率采样成 JPEG 帧
+  // 实测（2026-09-22）：同一串数字按 1/4/12 fps 发进 Gemini Live，
+  //   1fps → 读到 9/10； 4fps → 10/10； 12fps 突发 → 8/10
+  // 即：**上游在 4fps 以内会把每一帧都吃掉**，不是文档说的"只按 1 FPS 处理"。
+  const cv = document.createElement('canvas');
+  const fps = Math.max(1, Math.min(8, parseInt($('fps').value, 10) || 4));
+  let inFlight = false;                     // 上一帧还没发完就跳过，避免堆积
+  log(`视觉帧率：${fps} fps`);
+  camTimer = setInterval(() => {
+    const v = $('preview');
+    if (!v.videoWidth || !ready || ws?.readyState !== 1 || inFlight) return;
+    inFlight = true;
+    const w = 768, h = Math.round(v.videoHeight * (768 / v.videoWidth));
+    cv.width = w; cv.height = h; cv.getContext('2d').drawImage(v, 0, 0, w, h);
+    cv.toBlob((b) => {
+      if (!b) { inFlight = false; return; }
+      b.arrayBuffer().then((ab) => {
+        if (ws?.readyState === 1) {
+          ws.send(JSON.stringify({ type: 'image', data: b64(ab), mime: 'image/jpeg' }));
+        }
+        inFlight = false;
+      }).catch(() => { inFlight = false; });
+    }, 'image/jpeg', 0.6);
+  }, Math.round(1000 / fps));
+
+  try { wakeLock = await navigator.wakeLock?.request('screen'); log('已申请屏幕常亮'); } catch (e) {}
+}
+
+function stop() {
+  camTimer && clearInterval(camTimer); camTimer = null;
+  try { ws?.send(JSON.stringify({ type: 'stop' })); } catch (e) {}
+  ws?.close(); ws = null; ready = false;
+  micNode?.disconnect(); $('preview').srcObject?.getTracks().forEach(t => t.stop());
+  wakeLock?.release?.(); wakeLock = null;
+  audioCtx?.close(); audioCtx = null; playHead = 0;
+  $('start').disabled = false; $('stop').disabled = true; setState('已停止'); log('已停止');
+}
+
+$('start').onclick = start;
+$('stop').onclick = stop;
+$('sendText').onclick = () => {
+  const t = $('textInput').value.trim(); if (!t || ws?.readyState !== 1) return;
+  ws.send(JSON.stringify({ type: 'text', text: t })); log('你(文字): ' + t); $('textInput').value = '';
+};
+$('textInput').addEventListener('keydown', (e) => { if (e.key === 'Enter') $('sendText').click(); });
+
+// 上游实现的展示名：演示时一眼看出跑的是哪家
+const IMPL_LABEL = {
+  qwen: { name: 'Qwen 3.5 Omni Realtime', cls: 'up-qwen' },
+  adk:  { name: 'Gemini 3.8 Live',        cls: 'up-google' },
+  raw:  { name: 'Gemini 3.8 Live',        cls: 'up-google' },
+};
+
+function paintUpstream(d) {
+  const info = IMPL_LABEL[d.impl] || { name: d.impl || '未知实现', cls: 'up-unk' };
+  const th = d.thinking || {};
+  $('upstream').className = `card up ${info.cls}`;
+  // Gemini 图标只在 Gemini 系上显示（切到 Qwen 时隐藏）
+  $('upIcon').style.display = (d.impl === 'adk' || d.impl === 'raw') ? '' : 'none';
+  $('upName').textContent = info.name;
+  const ep = (d.endpoint || '').split('/')[0];   // 只显示 host，手机上一行放得下
+  $('upSub').textContent = `impl=${d.impl || '?'} · model=${d.model || '?'}` +
+    ` · voice=${d.voice || '-'}` + (ep ? ` · ${ep}` : '');
+  $('upstream').style.display = 'flex';
+  // Qwen 等无 thinking 档的实现：禁用选择器
+  const sel = $('thinking');
+  if (th.supported === false) {
+    sel.disabled = true;
+    sel.title = th.notes || '当前上游无推理档位';
+  } else {
+    sel.disabled = false;
+  }
+}
+
+function refreshStatus() {
+  return fetch('/api/status').then(r => r.json()).then(d => {
+    paintUpstream(d);
+    const keyTxt = d.key_present === true ? '已配置' : d.key_present === false ? '缺失' : '未知';
+    log(`服务端: impl=${d.impl || '?'} model=${d.model} voice=${d.voice || '-'} proxy=${d.proxy || '直连'} key=${keyTxt}${d.key_source ? ` (${d.key_source})` : ''}`);
+    log(`pi 桥接: ${JSON.stringify(d.bridge)}`);
+    // 只在服务端明确回答 key_present=false 时告警；字段缺失（老版本服务端）不算缺失
+    if (d.key_present === false) {
+      const name = d.impl === 'qwen' ? 'DASHSCOPE_API_KEY' : 'GEMINI_API_KEY';
+      $('secWarn').style.display = 'block';
+      $('secWarn').textContent = `⚠ 服务端未找到 ${name}` + (d.key_warning ? ` — ${d.key_warning}` : '');
+    }
+  }).catch(e => log('状态查询失败: ' + e.message));
+}
+
+// 屏幕共享时禁用「镜头」选择（摄像头才需要选镜头）
+function syncCams() {
+  const m = pick('source');
+  const sel = $('camPicker');
+  sel.disabled = (m === 'display');
+  sel.title = m === 'display' ? '屏幕共享模式下不需要选镜头' : '';
+}
+document.querySelectorAll('input[name=source]').forEach((r) => r.addEventListener('change', syncCams));
+syncCams();
+
+loadPersonas();
+// 恢复上次选的推理档位；Qwen 侧会由 /api/status 自动禁用
+(() => { try { const v = localStorage.getItem('live.thinking');
+  if (v !== null && $('thinking')) $('thinking').value = v; } catch (e) {} })();
+(() => { try { const v = localStorage.getItem('live.fps');
+  if (v !== null && $('fps')) $('fps').value = v; } catch (e) {} })();
+refreshCams();          // 页面加载先列一次（label 可能为空，取流后会再刷新）
+refreshStatus();
+</script>
+</body>
+</html>
